const chapters = [];
if(/\/chapter\//.test(baseUrl)) {
  let doc = org.jsoup.Jsoup.parse(result);
  let elements = doc.select(".chapListBody a");
  elements.forEach(a => {
    let text = a.text().trim();
    let href = a.attr("href");
    chapters.push({text, href})
  })
