  }));
  return host + '/index.php?action=loadChapterPage,' + JSON.stringify({
	   "method": "POST",
	   "body": "data="+encodeURIComponent(postBody)
  })
});

return nextpages
})()

source.searchUrl:
@js:
/**
 * 对齐网站搜索规则前置校验
 * 1. 去除首尾空格
 * 2. 字数限制：2～8个字
 * 3. 拦截高危特殊符号，只允许常规中文、字母、数字、常用中文标点
 * 非法特殊符号：引号、斜杠、括号、@#$^&*{}[]等脚本危险字符
 */
function checkKeywordLegal(word) {
    const trimWord = String(word).trim();
    const kwLen = trimWord.length;
    // 空值拦截
    if (kwLen === 0) {
        java.longToast("搜索关键词不能为空");
        throw new Error("搜索关键词不能为空");
    }
    // 字数校验 2～8位
    if (kwLen < 2 || kwLen > 8) {
    	   java.longToast("搜索关键字只允许2~8个字之间");
        throw new Error("搜索关键字只允许2~8个字之间");
    }
    // 禁止高危特殊符号正则
    const forbidReg = /[\\\"\(\)\{\}\[\]<>@#$%^&*;:|~]/;
    if (forbidReg.test(trimWord)) {
    	   java.longToast("关键词包含非法特殊符号，请重新输入");
        throw new Error("关键词包含非法特殊符号，请重新输入");
    }
}

// JS字符串转义兜底，防止注入语法报错
function jsStrEscape(str) {
    if (str == null) return "";
    return String(str)
        .replace(/\\/g, "\\\\")
        .replace(/"/g, '\\"')
        .replace(/\n/g, "\\n")
        .replace(/\r/g, "\\r")
        .replace(/\t/g, "\\t");
}
// 最先执行关键词校验，不合法直接抛出，终止全部后续流程
checkKeywordLegal(key);

var host = "https://www.rrssk.com";
var homeUrl = host + "/0005.html";

// 缓存Key定义
const KEY_HOME_HTML = "home_html_data";
const KEY_HOME_STAMP = "home_html_timestamp";
const KEY_SIGNJS_VAL = "daily_signjs_value";
const KEY_SIGNJS_STAMP = "daily_signjs_timestamp";

// 时效配置（单位：秒）
const HOME_TTL = 120;
const SIGNJS_TTL = 21600;

// public.js 固定硬编码
const publicJsCode = `
// rrssk public.js v11
function __enc(x) {
    return encodeURIComponent(x).replace(/[!'()*]/g, function(c) {
        return '%' + c.charCodeAt(0).toString(16).toUpperCase();
    });
}
function __signData(kw, t) {
    if (!window.__SIGN || typeof window.__SIGN.f !== 'function') return null;
    var ts = Math.floor(Date.now() / 1000);
    return { ts: ts, s: window.__SIGN.f(__enc(kw), t, ts) };
}
`;

const nowSecond = Math.floor(Date.now() / 1000);

// 读取首页缓存，双重校验过期
let homeHtmlRaw = null;
const cacheHome = cache.get(KEY_HOME_HTML);
const cacheHomeStamp = Number(cache.get(KEY_HOME_STAMP) || 0);
// 缓存存在 + 手动时间未超时才复用
if (cacheHome && cacheHomeStamp && (nowSecond - cacheHomeStamp < HOME_TTL)) {
    homeHtmlRaw = cacheHome;
}

// 过期|无缓存，重新拉取
if (!homeHtmlRaw) {
    homeHtmlRaw = String(java.ajax(homeUrl));
    cache.put(KEY_HOME_HTML, homeHtmlRaw, HOME_TTL);
    cache.put(KEY_HOME_STAMP, String(nowSecond), HOME_TTL);
}

// 解析页面关键内容
const tMatch = homeHtmlRaw.match(/name="_t" value="([^"]+)"/);
const apiMatch = homeHtmlRaw.match(/action=["'](\/\?action=\w+)["']/);
const signJsLinkMatch = homeHtmlRaw.match(/<script src="(\/\?action=signJs[^"]+)"/);

if (!tMatch) {
	   java.longToast("页面解析失败：未获取_t签名令牌");
    throw new Error("页面解析失败：未获取_t签名令牌");
}
if (!apiMatch) {
	   java.longToast("页面解析失败：未获取搜索接口地址");
    throw new Error("页面解析失败：未获取搜索接口地址");
}
if (!signJsLinkMatch) {
	   java.longToast("页面解析失败：未匹配signJs脚本链接");
    throw new Error("页面解析失败：未匹配signJs脚本链接");
};

const tokenT = tMatch[1];
const searchApi = apiMatch[1];

// signJs 双重过期校验
let signJsCode = null;
const cacheSignJsVal = cache.get(KEY_SIGNJS_VAL);
const cacheSignJsStamp = Number(cache.get(KEY_SIGNJS_STAMP) || 0);
if (cacheSignJsVal && cacheSignJsStamp && (nowSecond - cacheSignJsStamp < SIGNJS_TTL)) {
    signJsCode = cacheSignJsVal;
}

if (!signJsCode) {
    const signJsUrl = host + signJsLinkMatch[1];
    signJsCode = String(java.ajax(signJsUrl));
    cache.put(KEY_SIGNJS_VAL, signJsCode, SIGNJS_TTL);
    cache.put(KEY_SIGNJS_STAMP, String(nowSecond), SIGNJS_TTL);
}

// 简化页面
let renderHtml = homeHtmlRaw
    .replace(/<link[^>]*>/gi, '')
    .replace(/<img[^>]*>/gi, '')
    .replace(/<svg[\s\S]*?<\/svg>/gi, '')
    .replace(/<footer[\s\S]*?<\/footer>/gi, '')
    .replace(/<script src="\/templates\/js\/jquery[\s\S]*?<\/script>/, '')
    .replace(/<script src="\/templates\/js\/public\.js[\s\S]*?<\/script>/, `<script>${publicJsCode}</script>`)
    .replace(/<script src="\/\?action=signJs[\s\S]*?<\/script>/, `<script>${signJsCode}</script>`);

// 执行签名
const safeKey = jsStrEscape(key);
const injectScript = `const res = __signData("${safeKey}","${tokenT}"); res ? res.s : null;`;
const signResult = String(java.webView(renderHtml, homeUrl, injectScript, false));

if (!signResult || signResult === "00000000") {
	   java.longToast("签名失败：WebView环境指纹校验不通过");
    throw new Error("签名失败：WebView环境指纹校验不通过");
}

// 拼装POST参数
const postBody = "_t=" + encodeURIComponent(tokenT)
    + "&_ts=" + Math.floor(Date.now() / 1000)
    + "&_s=" + encodeURIComponent(signResult)
    + "&keyword=" + encodeURIComponent(key);

host + searchApi + "," + JSON.stringify({
    method: "POST",
    body: postBody
});

